UPDATE products SET reserved_quantity=1 WHERE id IN (1,2,3,4) AND reserved_quantity=0;
UPDATE products SET stock_quantity=19, sales_count=1 WHERE id=5 AND stock_quantity=20;
UPDATE products p SET review_count=(SELECT count(*) FROM reviews r WHERE r.product_id=p.id AND r.status='APPROVED'), average_rating=COALESCE((SELECT round(avg(rating)::numeric,2) FROM reviews r WHERE r.product_id=p.id AND r.status='APPROVED'),0);
